  'Algo delicioso': { en: 'Something delicious', fr: 'Quelque chose de délicieux', de: 'Etwas Köstliches', 'es-ES': 'Algo delicioso', 'zh-CN': '美味佳肴' },
  'te espera.': { en: 'is waiting for you.', fr: 'vous attend.', de: 'erwartet Sie.', 'es-ES': 'te espera.', 'zh-CN': '等着您。' },
  'Explora nuestra carta y envía tu selección. El equipo confirmará cada solicitud antes de enviarla a cocina.': { en: 'Explore our menu and send your selections. The team will confirm each request before sending it to the kitchen.', fr: 'Découvrez notre menu et envoyez votre sélection. L’équipe confirmera chaque demande avant de la transmettre en cuisine.', de: 'Entdecken Sie unsere Speisekarte und senden Sie Ihre Auswahl. Das Team bestätigt jede Anfrage, bevor sie an die Küche geht.', 'es-ES': 'Explora nuestra carta y envía tu selección. El equipo confirmará cada solicitud antes de enviarla a cocina.', 'zh-CN': '浏览菜单并提交选择。团队会在发送至厨房前确认每项请求。' },
  'PRIVADO EN ESTE DISPOSITIVO': { en: 'PRIVATE ON THIS DEVICE', fr: 'PRIVÉ SUR CET APPAREIL', de: 'PRIVAT AUF DIESEM GERÄT', 'es-ES': 'PRIVADO EN ESTE DISPOSITIVO', 'zh-CN': '仅在此设备上可见' },
  'Mis pedidos': { en: 'My orders', fr: 'Mes commandes', de: 'Meine Bestellungen', 'es-ES': 'Mis pedidos', 'zh-CN': '我的订单' },
