  'Ingrediente a retirar (por alergia o preferencia)': { en: 'Ingredient to remove (allergy or preference)', fr: 'Ingrédient à retirer (allergie ou préférence)', de: 'Zu entfernende Zutat (Allergie oder Vorliebe)', 'es-ES': 'Ingrediente que retirar (por alergia o preferencia)', 'zh-CN': '需要去除的食材（过敏或个人偏好）' },
  'Ej. maní, queso, cilantro': { en: 'E.g. peanuts, cheese, cilantro', fr: 'Ex. arachides, fromage, coriandre', de: 'Z. B. Erdnüsse, Käse, Koriander', 'es-ES': 'Ej. cacahuetes, queso, cilantro', 'zh-CN': '例如：花生、奶酪、香菜' },
  'Guardar indicación': { en: 'Save note', fr: 'Enregistrer la note', de: 'Hinweis speichern', 'es-ES': 'Guardar indicación', 'zh-CN': '保存备注' },
