  'Atención alergias:': { en: 'Allergy notice:', fr: 'Attention aux allergies :', de: 'Allergiehinweis:', 'es-ES': 'Atención con las alergias:', 'zh-CN': '过敏提示：' },
  'confirma la solicitud con cocina. Esta indicación no garantiza ausencia de contaminación cruzada.': { en: 'confirm this request with the kitchen. This note does not guarantee the absence of cross-contamination.', fr: 'confirmez cette demande avec la cuisine. Cette note ne garantit pas l’absence de contamination croisée.', de: 'Bestätigen Sie diese Anfrage mit der Küche. Dieser Hinweis garantiert keine Abwesenheit von Kreuzkontamination.', 'es-ES': 'confirma esta solicitud con cocina. Esta indicación no garantiza la ausencia de contaminación cruzada.', 'zh-CN': '请与厨房确认此请求。该备注不保证没有交叉污染。' },
  'Agregar al pedido': { en: 'Add to order', fr: 'Ajouter à la commande', de: 'Zur Bestellung hinzufügen', 'es-ES': 'Agregar al pedido', 'zh-CN': '添加到订单' },
  '{count} disponibles · $ {price} COP': { en: '{count} available · $ {price} COP', fr: '{count} disponible(s) · {price} $ COP', de: '{count} verfügbar · {price} COP', 'es-ES': '{count} disponibles · $ {price} COP', 'zh-CN': '可用 {count} 件 · $ {price} COP' },
  'No hay productos disponibles en el menú.': { en: 'There are no products available on the menu.', fr: 'Aucun produit n’est disponible au menu.', de: 'Es sind keine Produkte auf der Speisekarte verfügbar.', 'es-ES': 'No hay productos disponibles en el menú.', 'zh-CN': '菜单中没有可用商品。' },
  'Pago recibido en caja': { en: 'Payment received at checkout', fr: 'Paiement reçu en caisse', de: 'Zahlung an der Kasse erhalten', 'es-ES': 'Pago recibido en caja', 'zh-CN': '收银处已收款' },
